INSERT INTO sources (id, url, title, domain, source_type, accessed_at, is_official, is_verified, created_at) VALUES (3129, 'https://www.gu.se/sites/default/files/2026-10/Axel%20Adler%20Scholarship%20requirements%202027_1.pdf', $$Requirements for the Axel Adler Scholarship 2027 (PDF) | University of Gothenburg International Centre (official)$$, 'gu.se', 'scholarship', now(), true, true, now()), (3130, 'https://www.gu.se/en/study-in-gothenburg/apply/scholarships-for-fee-paying-students/scholarships-for-students-at-the-school-of-business-economics-and-law', $$Scholarships for students at the School of Business, Economics and Law (Richard C. Malmsten Memorial Foundation Scholarship) | University of Gothenburg (official)$$, 'gu.se', 'scholarship', now(), true, true, now()), (3131, 'https://liu.se/en/article/scholarships', $$Scholarships - LiU International Scholarship | Linköping University (official)$$, 'liu.se', 'scholarship', now(), true, true, now()) RETURNING id, url;

-- 2) Uplift 739 rel 9 -> 10 (genuine scholarship window 10 Feb - 8 Mar 2027 from the PDF;
