-- 7) university_scholarships sync
UPDATE university_scholarships SET university_id = 136, scholarship_name = $$Axel Adler Scholarship (University of Gothenburg)$$, availability_status = $$available$$, funding_type = $$Tuition fee waiver funded by foundations$$, valued_aspect = $$CV and letter of motivation (max 3,000 characters each) ranked by academic staff, plus academic merits$$, eligibility_notes = $$Verified 2026-10-25 and uplifted 2026-10-28 from the official Axel Adler page (modified 2026-10-08) and the Axel Adler Scholarship 2027 requirements PDF. No citizenship restriction - the condition is being required to pay tuition fees in Sweden. Full tuition waiver for the whole programme (120 cr master / 60 cr 1-year / 180 cr bachelor) plus FAS+ insurance; no living-cost or travel support. One award per master programme and per eligible bachelor programme, four across the Artistic Faculty, up to ten extra if funds allow. Mechanics 2027: GU programme as first priority and studies application by 15 Jan 2027, fee and documents by 1 Feb 2027, invitation email around 10 Feb, scholarship application 10 Feb-8 Mar 2027, results 12 Apr (master) / 15 Apr 2027 (bachelor). Cannot be combined with another tuition scholarship; keep at least 75% of each semester credits; residence permit must be in time or the award is withdrawn. Siblings: Sustainability variant (record 967) and Malmsten business scholarship (record 988).$$ , official_url = $$https://www.gu.se/en/study-in-gothenburg/apply/scholarships-for-fee-paying-students/axel-adler-scholarship$$, verification_status = $$verified$$, last_verified_at = now(), scholarship_id = 739 WHERE id = 130 RETURNING id;

INSERT INTO university_scholarships (id, university_id, scholarship_id, scholarship_name, availability_status, funding_type, max_scholarship, covers_tuition, covers_living_expenses, valued_aspect, eligibility_notes, official_url, source_url, verification_status, last_verified_at, created_at) VALUES (711, 136, 988, $$Richard C. Malmsten Memorial Foundation Scholarship$$, $$available$$, $$Partial Tuition$$, $$SEK 100,000 over two years (tuition fee waiver of SEK 25,000 per semester)$$, true, false, $$GMAT score ranking - applicants without a GMAT score are not considered$$, $$New record verified 2026-10-28 from the official GU School of Business, Economics and Law scholarships page (modified 2026-10-15). For fee-paying students admitted to one of the nine Graduate School MSc programmes; ranked by GMAT score (sent by the test organisation to the School); first-priority applicants prioritised; holders of Swedish Institute or University of Gothenburg study scholarships are excluded; selection committee decision final. Awarded once a year: 2026 round ran 3 Feb-17 Mar 2026; 2027 round information to be published November 2026. Covers part of tuition only.$$ , $$https://www.gu.se/en/study-in-gothenburg/apply/scholarships-for-fee-paying-students/scholarships-for-students-at-the-school-of-business-economics-and-law$$, $$https://www.gu.se/en/study-in-gothenburg/apply/scholarships-for-fee-paying-students/scholarships-for-students-at-the-school-of-business-economics-and-law$$, $$verified$$, now(), now()) RETURNING id;

-- 8) Sequence housekeeping
SELECT setval('scholarships_id_seq', 989) AS sch_seq, setval('sources_id_seq', 3131) AS src_seq, setval('university_scholarships_id_seq', 711) AS us_seq;
